function promptSectionLabel(name: string): string {
  return name === "project_context" ? "project" : name;
}

const PROMPT_BREAKDOWN_MAX_SECTIONS = 7;

function packPromptPairs(items: string[], maxWidth: number): string[] {
  const lines: string[] = [];
  let current = "";
  for (const item of items) {
    if (current.length === 0) {
      current = item;
    } else if (visibleWidth(current) + 3 + visibleWidth(item) <= maxWidth) {
      current += ` · ${item}`;
    } else {
      lines.push(current);
      current = item;
    }
  }
  if (current.length > 0) lines.push(current);
  return lines;
}

function promptSectionPairs(sections: PromptBreakdownSection[]): string[] {
  const pairs = sections.map((section) => `${promptSectionLabel(section.name)} ${formatTokens(section.tokens)}`);
  if (pairs.length <= PROMPT_BREAKDOWN_MAX_SECTIONS) return pairs;

  const head = pairs.slice(0, PROMPT_BREAKDOWN_MAX_SECTIONS - 1);
  const rest = sections
    .slice(PROMPT_BREAKDOWN_MAX_SECTIONS - 1)
    .reduce((sum, section) => sum + section.tokens, 0);
  head.push(`other ${formatTokens(rest)}`);
  return head;
}

/**
 * Initial-prompt breakdown: the system prompt split by section, then the tool declarations.
 * Falls back to the caller's single-line total when no breakdown data is available.
 */
function buildPromptBreakdownLines(data: WelcomeData, colWidth: number): string[] {
  const breakdown = data.promptBreakdown;
  const total = data.initialContextTokens;
  if (breakdown === null || total === null || !Number.isFinite(total) || total <= 0) {
    return [];
  }

  const itemPrefix = dim("- ");
  const lines = [
    ` ${itemPrefix}${fgOnly("gitClean", `≈ ${formatTokens(total)}`)} initial prompt tokens`,
    `  ${dim("├")} ${dim(`system prompt ${formatTokens(breakdown.system)}`)}`,
  ];

  const packed = packPromptPairs(promptSectionPairs(breakdown.sections), Math.max(12, colWidth - 7));
  for (const line of packed) {
    lines.push(`  ${dim("│")}   ${dim(line)}`);
  }

  if (breakdown.tools > 0) {
    lines.push(`  ${dim("└")} ${dim(`tool schema ${formatTokens(breakdown.tools)} (${breakdown.toolCount})`)}`);
  }
  return lines;
}

