function fitToWidth(str: string, width: number): string {
  const visLen = visibleWidth(str);
  if (visLen > width) {
    // [pi-zh fit-to-width] 窄终端 + 中文场景下，tuiTruncateToWidth 为避免劈开全角字符
    // 可能返回 width-1 列，导致欢迎框右边框错位。此处补齐到 width。
    // 回退分支：未触发达标长度时行为与上游完全一致（仍在超宽时截断并加省略号）。
    const truncated = tuiTruncateToWidth(str, width, "…");
    const truncatedLen = visibleWidth(truncated);
    return truncatedLen < width ? truncated + " ".repeat(width - truncatedLen) : truncated;
  }
  return str + " ".repeat(width - visLen);
}

