export interface PromptBreakdownSection {
  name: string;
  tokens: number;
}

/** Initial prompt estimate split into system-prompt sections and tool declarations. */
export interface PromptBreakdown {
  /** Whole system prompt, tagged sections plus any untagged remainder. */
  system: number;
  /** Tool declarations Pi sends next to the system prompt. */
  tools: number;
  toolCount: number;
  sections: PromptBreakdownSection[];
  /** system + tools: the number the welcome panel headlines. */
  total: number;
}

function estimateCharsToTokens(chars: number): number {
  return Math.ceil(chars / 4);
}

/**
 * Split a rendered system prompt back into the tagged sections Pi built it from
 * (`<rules>…</rules>`, `<skills>…</skills>`, …). Prompts without tags come back as one section.
 */
export function splitSystemPromptSections(prompt: string): PromptBreakdownSection[] {
  const sections: PromptBreakdownSection[] = [];
  const pattern = /<([a-z][a-z0-9_]*)>\n([\s\S]*?)\n<\/\1>/g;
  let match = pattern.exec(prompt);
  while (match !== null) {
    sections.push({ name: match[1], tokens: estimateCharsToTokens(match[0].length) });
    match = pattern.exec(prompt);
  }
  if (sections.length === 0 && prompt.trim().length > 0) {
    sections.push({ name: "system", tokens: estimateCharsToTokens(prompt.length) });
  }
  return sections;
}

function readActiveToolNames(extensionApi: Record<string, unknown>): Set<string> | null {
  const getActiveTools = extensionApi.getActiveTools;
  if (typeof getActiveTools !== "function") return null;
  try {
    const active = getActiveTools.call(extensionApi);
    if (!Array.isArray(active)) return null;
    return new Set(active.filter((name): name is string => typeof name === "string"));
  } catch {
    return null;
  }
}

function collectActiveToolDeclarations(extensionApi: unknown): Array<Record<string, unknown>> {
  if (!isRecord(extensionApi)) return [];
  const getAllTools = extensionApi.getAllTools;
  if (typeof getAllTools !== "function") return [];
  let tools: unknown;
  try {
    tools = getAllTools.call(extensionApi);
  } catch {
    return [];
  }
  if (!Array.isArray(tools)) return [];
  const activeNames = readActiveToolNames(extensionApi);
  return tools
    .filter((tool): tool is Record<string, unknown> => isRecord(tool))
    .filter((tool) => activeNames === null || (typeof tool.name === "string" && activeNames.has(tool.name)));
}

/**
 * Estimate the initial prompt the way the welcome panel reports it: every system-prompt section
 * plus the tool declarations. Tool schemas travel as their own request field, so counting only the
 * prompt text understates the first request by the size of the whole tool set.
 */
export function estimatePromptBreakdown(ctx: unknown, extensionApi?: unknown): PromptBreakdown | null {
  if (!isRecord(ctx) || typeof ctx.getSystemPrompt !== "function") return null;

  let prompt: unknown;
  try {
    prompt = ctx.getSystemPrompt();
  } catch {
    return null;
  }
  if (typeof prompt !== "string" || prompt.trim().length === 0) return null;

  const declarations = collectActiveToolDeclarations(extensionApi).map((tool) => ({
    name: typeof tool.name === "string" ? tool.name : "tool",
    description: typeof tool.description === "string" ? tool.description : "",
    parameters: isRecord(tool.parameters) ? tool.parameters : {},
  }));

  const system = estimateCharsToTokens(prompt.length);
  const tools = declarations.length > 0 ? estimateCharsToTokens(JSON.stringify(declarations).length) : 0;

  return {
    system,
    tools,
    toolCount: declarations.length,
    sections: splitSystemPromptSections(prompt),
    total: system + tools,
  };
}

